/* A registry MISS used to be called straight through -- i.e. a call to NULL,
   which lands as a bare SIGSEGV with nothing pointing at the cause.  Only a
   value whose CPS entry was registered at startup can thread the handler
   chain, so a miss is a compiler bug, not a user error; say so and stop. */
__attribute__((unused)) static __tur_cps_fn __tur_cps_lookup_checked(intptr_t direct,
                                                                     const char *who) {
    __tur_cps_fn f = __tur_cps_lookup(direct);
    if (!f) {
        fprintf(stderr, "tur: internal error: no CPS entry registered for "
                        "effectful fn-value '%s' -- it cannot thread the "
                        "effect handler chain\n", who ? who : "?");
        abort();
    }
    return f;
}
/* Structural-chain reaping (docs/archive/cps-delimited-dk-node-leak.md).
 * reset/handle install a prompt/handler chain as the current continuation and
 * thread it through the delimited body in TAIL position, so the install site
 * never regains control to free it.  Each chain is self-contained (its tail is
 * dk_done; its frame envs carry the enclosing k as an intptr, not via ->next),
 * so once the outermost dk_run has fully settled every registered chain is dead
 * and dk_free-able without aliasing another.  We register each at construction
 * and reap at the outermost direct->cps entry boundary.  The same registry
 * reclaims per-continuation env structs (plain malloc, freed one-by-one).
 *
 * dk-reap-list-shared-across-threads: the registry, the entry depth and the
 * trampoline's state below are per-thread.  Shared, a CPS entry on one thread
 * pushed onto the list another thread was reallocating, a worker's exit that
 * took the depth to 0 freed every thread's live chains, and a worker's entry
 * overwrote the landing another thread's tail-resume longjmps to.  A fiber
 * carries its own registry and depth across its switches (FiberBlock,
 * tur_fiber_block_resume), since it can resume on another thread. */
