#define __dk_reap_kind (*(unsigned char **)tur_tls_dk_reap_kind_ptr())
#define __dk_reap_n (*tur_tls_dk_reap_n_ptr())
#define __dk_reap_cap (*tur_tls_dk_reap_cap_ptr())
#define __dk_entry_depth (*tur_tls_dk_entry_depth_ptr())
