    s->orphaned = true;
    for (DK *p = s->next; p && !(p->kind == DKK_PROMPT && p->tag == s->tag) && p->kind != DKK_DONE; p = p->next) {
        p->orphaned = true;
        if (parked && p->ncopy == 1 && p->env_size && !p->env_owned) p->orphan_env = true;
    }
